style.css:
@-moz-document domain("youtube.com") {
/* ---------- VARIABLES (edita aquí lo importante) ---------- */
  :root {
    /* 1) FONDO: pega aquí el enlace DIRECTO de la imagen (termina en .jpg/.png) */
    /* Stylish exige una URL completa (https://...). Mientras no tengas el link, déjalo en none.
       Cuando lo tengas, reemplaza la línea de abajo por:
       --fondo-img: url("https://i.pinimg.com/originals/xx/xx/xx/tuimagen.jpg"); */
    --fondo-img: none;

    /* 2) Paleta roja */
    --rojo-oscuro: #3a0000;
    --rojo-medio: #8c0a0a;
    --rojo-vivo: #d60f0f;
    --rojo-brillo: #ff3b3b;
    --negro: #0a0000;
    --texto: #ffffff;
    --texto-suave: #ffd6d6;

    /* 3) Fuentes góticas */
    --fuente-titulos: 'UnifrakturCook', 'UnifrakturMaguntia', 'Old English Text MT', 'Blackadder ITC', serif;
    --fuente-texto: 'Pirata One', 'UnifrakturMaguntia', 'Old English Text MT', 'Blackadder ITC', serif;

    /* Sobrescribir variables internas de YouTube */
    --yt-spec-base-background: transparent !important;
    --yt-spec-raised-background: rgba(120, 0, 0, 0.55) !important;
    --yt-spec-menu-background: #4a0000 !important;
    --yt-spec-general-background-a: transparent !important;
    --yt-spec-general-background-b: rgba(90, 0, 0, 0.55) !important;
    --yt-spec-general-background-c: rgba(60, 0, 0, 0.6) !important;
    --yt-spec-text-primary: #ffffff !important;
    --yt-spec-text-secondary: #ffd6d6 !important;
    --yt-spec-call-to-action: #ff5a5a !important;
    --yt-spec-brand-background-solid: #8c0a0a !important;
    --yt-spec-badge-chip-background: rgba(255, 255, 255, 0.12) !important;
    --yt-spec-10-percent-layer: rgba(255, 120, 120, 0.25) !important;
    --yt-spec-static-overlay-background-solid: #3a0000 !important;
  }

  /* ---------- FONDO GENERAL ---------- */
  html,
  body,
  ytd-app {
    background-color: var(--rojo-oscuro) !important;
    background-image:
      radial-gradient(rgba(0, 0, 0, 0.35) 1.2px, transparent 1.4px),
      var(--fondo-img),
      linear-gradient(160deg, #a30000 0%, #5c0000 55%, #1a0000 100%) !important;
    background-size: 9px 9px, cover, cover !important;
    background-position: 0 0, center bottom, center !important;
    background-repeat: repeat, no-repeat, no-repeat !important;
    background-attachment: fixed !important;
  }

  /* Hacer transparentes los contenedores para que se vea el fondo */
  ytd-page-manager,
  ytd-browse,
  ytd-watch-flexy,
  ytd-search,
  ytd-two-column-browse-results-renderer,
  ytd-two-column-search-results-renderer,
  #page-manager,
  #content,
  #primary,
  #secondary,
  ytd-shorts,
  #shorts-container,
  ytd-rich-grid-renderer,
  ytd-section-list-renderer {
    background: transparent !important;
  }

  /* ---------- BARRA SUPERIOR (efecto cristal rojo brillante) ---------- */
  #masthead-container,
  ytd-masthead,
  #background.ytd-masthead {
    background: linear-gradient(180deg, #c40000 0%, #7a0000 55%, #4a0000 100%) !important;
    border-bottom: 1px solid rgba(255, 140, 140, 0.45) !important;
    box-shadow: 0 3px 14px rgba(0, 0, 0, 0.6) !important;
  }

  /* Buscador */
  yt-searchbox,
  #search-form,
  ytd-searchbox #container,
  yt-searchbox .ytSearchboxComponentInputBox {
    background: rgba(90, 0, 0, 0.65) !important;
    border: 1px solid rgba(255, 140, 140, 0.5) !important;
    border-radius: 40px !important;
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.55) !important;
  }
  input#search,
  yt-searchbox input {
    color: #fff !important;
    font-family: var(--fuente-texto) !important;
    font-size: 18px !important;
  }
  #search-icon-legacy,
  .ytSearchboxComponentSearchButton {
    background: rgba(140, 0, 0, 0.7) !important;
    border-left: 1px solid rgba(255, 140, 140, 0.4) !important;
  }

  /* Botón de micrófono, Crear y notificaciones: estilo botón brillante */
  #voice-search-button button,
  ytd-masthead #buttons ytd-button-renderer a,
  ytd-masthead #buttons yt-button-shape button,
  ytd-masthead ytd-notification-topbar-button-renderer button {
    background: radial-gradient(circle at 30% 25%, #ff6a6a 0%, #b00000 45%, #4a0000 100%) !important;
    border: 2px solid rgba(255, 255, 255, 0.35) !important;
    border-radius: 50px !important;
    box-shadow:
      0 0 10px rgba(0, 0, 0, 0.7),
      inset 0 2px 4px rgba(255, 255, 255, 0.45) !important;
    color: #fff !important;
  }

  /* ---------- MENÚ LATERAL (suscripciones / Tú / Explorar / más de YouTube) ---------- */
  tp-yt-app-drawer,
  ytd-mini-guide-renderer,
  ytd-guide-renderer,
  #guide-inner-content,
  #guide-content,
  #guide,
  ytd-guide-section-renderer,
  ytd-guide-collapsible-section-entry-renderer,
  ytd-guide-collapsible-entry-renderer,
  #sections.ytd-guide-renderer,
  tp-yt-app-drawer #contentContainer {
    background:
      linear-gradient(180deg, rgba(100, 0, 0, 0.88) 0%, rgba(45, 0, 0, 0.94) 100%) !important;
    border-right: 1px solid rgba(255, 120, 120, 0.35) !important;
    box-shadow: 4px 0 18px rgba(0, 0, 0, 0.45) !important;
    backdrop-filter: blur(6px);
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    border-radius: 14px !important;
    margin: 2px 6px !important;
  }
  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: linear-gradient(180deg, rgba(255, 90, 90, 0.35), rgba(160, 0, 0, 0.45)) !important;
    box-shadow: inset 0 1px 3px rgba(255, 255, 255, 0.35) !important;
  }
  ytd-guide-entry-renderer[active],
  ytd-mini-guide-entry-renderer[active],
  ytd-guide-entry-renderer.iron-selected {
    background: linear-gradient(180deg, #d60f0f, #7a0000) !important;
    box-shadow: 0 0 10px rgba(255, 60, 60, 0.6) !important;
  }
  ytd-guide-section-renderer #guide-section-title,
  ytd-guide-section-renderer h3 {
    font-family: var(--fuente-titulos) !important;
    color: #ffb3b3 !important;
    font-size: 20px !important;
  }
  ytd-guide-renderer #footer,
  #footer.ytd-guide-renderer {
    background: transparent !important;
  }

  /* ---------- CHIPS / CATEGORÍAS (Todo, Música, Mixes...) ---------- */
  ytd-feed-filter-chip-bar-renderer,
  #chips-wrapper,
  ytd-feed-filter-chip-bar-renderer #chips-wrapper {
    background: transparent !important;
  }
  yt-chip-cloud-chip-renderer,
  yt-chip-cloud-chip-renderer.ytChipShapeChip,
  .ytChipShapeChip {
    background: transparent !important;
    color: #fff !important;
    font-family: var(--fuente-texto) !important;
    font-size: 17px !important;
    border-radius: 20px !important;
  }
  yt-chip-cloud-chip-renderer[selected],
  .ytChipShapeActive {
    background: linear-gradient(180deg, #ff4a4a, #a00000) !important;
    color: #fff !important;
    box-shadow: 0 0 8px rgba(255, 60, 60, 0.6) !important;
  }

  /* ---------- TARJETAS DE VIDEO (cristal rojo) ---------- */
  ytd-rich-item-renderer #content,
  ytd-video-renderer,
  ytd-compact-video-renderer,
  ytd-grid-video-renderer,
  ytd-playlist-renderer,
  ytd-channel-renderer,
  yt-lockup-view-model {
    background: linear-gradient(180deg, rgba(190, 20, 20, 0.45), rgba(90, 0, 0, 0.55)) !important;
    border: 1px solid rgba(255, 140, 140, 0.35) !important;
    border-radius: 22px !important;
    box-shadow:
      0 6px 18px rgba(0, 0, 0, 0.55),
      inset 0 1px 3px rgba(255, 255, 255, 0.25) !important;
    padding: 10px !important;
    backdrop-filter: blur(4px);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }
  ytd-rich-item-renderer:hover #content,
  ytd-video-renderer:hover,
  ytd-compact-video-renderer:hover,
  yt-lockup-view-model:hover {
    transform: translateY(-3px) scale(1.01);
    box-shadow: 0 10px 26px rgba(255, 40, 40, 0.35) !important;
  }
  ytd-thumbnail,
  yt-thumbnail-view-model,
  ytd-thumbnail a,
  ytd-thumbnail img {
    border-radius: 16px !important;
  }

  /* Secciones de lista (resultados de búsqueda) */
  ytd-item-section-renderer,
  ytd-shelf-renderer {
    background: transparent !important;
  }

  /* ---------- REPRODUCTOR ---------- */
  .ytp-chrome-bottom {
    background: linear-gradient(0deg, rgba(120, 0, 0, 0.85), transparent) !important;
  }
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background: linear-gradient(90deg, #ff5a5a, #d60f0f) !important;
  }
  .ytp-scrubber-button {
    background: #ff3b3b !important;
  }

  /* Botones debajo del video (Me gusta, Compartir, Guardar...) */
  ytd-watch-metadata yt-button-shape button,
  ytd-watch-metadata ytd-subscribe-button-renderer button,
  ytd-watch-metadata like-button-view-model button,
  ytd-watch-metadata dislike-button-view-model button,
  ytd-watch-metadata .yt-spec-button-shape-next {
    background: linear-gradient(180deg, #d60f0f 0%, #6e0000 100%) !important;
    color: #fff !important;
    border: 2px solid rgba(255, 255, 255, 0.35) !important;
    border-radius: 40px !important;
    box-shadow: 0 0 8px rgba(0, 0, 0, 0.6), inset 0 2px 3px rgba(255, 255, 255, 0.4) !important;
    font-family: var(--fuente-texto) !important;
  }

  /* Botón Suscribirse / Suscrito */
  ytd-subscribe-button-renderer button,
  yt-subscribe-button-view-model button {
    background: linear-gradient(180deg, #2a0000, #000) !important;
    color: #fff !important;
    border: 2px solid rgba(255, 90, 90, 0.7) !important;
    border-radius: 40px !important;
  }

  /* Descripción, comentarios y panel lateral */
  ytd-watch-metadata #description,
  ytd-comments,
  ytd-comments-header-renderer,
  ytd-playlist-panel-renderer,
  ytd-engagement-panel-section-list-renderer,
  ytd-watch-next-secondary-results-renderer {
    background: rgba(70, 0, 0, 0.55) !important;
    border-radius: 18px !important;
  }
  ytd-watch-metadata #description {
    border: 1px solid rgba(255, 140, 140, 0.35) !important;
  }

  /* ---------- SHORTS ---------- */
  ytd-shorts .navigation-button button,
  ytd-reel-player-overlay-renderer yt-button-shape button {
    background: radial-gradient(circle at 30% 25%, #ff6a6a, #a00000 55%, #3a0000) !important;
    border: 2px solid rgba(255, 255, 255, 0.4) !important;
    border-radius: 50% !important;
    box-shadow: 0 0 10px rgba(0, 0, 0, 0.7), inset 0 2px 4px rgba(255, 255, 255, 0.45) !important;
  }

  /* ---------- MENÚS DESPLEGABLES / POPUPS ---------- */
  tp-yt-paper-listbox,
  ytd-menu-popup-renderer,
  ytd-multi-page-menu-renderer,
  ytd-popup-container tp-yt-paper-dialog,
  yt-contextual-sheet-layout {
    background: linear-gradient(180deg, #7a0000, #350000) !important;
    border: 1px solid rgba(255, 140, 140, 0.45) !important;
    border-radius: 18px !important;
    color: #fff !important;
  }

  /* ---------- TIPOGRAFÍA GÓTICA ---------- */
  html, body, ytd-app,
  yt-formatted-string, span, a, p, label, input, textarea, button, div {
    font-family: var(--fuente-texto) !important;
    letter-spacing: 0.3px;
  }

  /* Títulos con gótica más marcada */
  h1, h2, h3,
  #video-title,
  ytd-watch-metadata h1,
  ytd-rich-grid-media #video-title,
  yt-formatted-string.ytd-channel-name,
  #channel-name a,
  ytd-guide-section-renderer h3,
  ytd-shelf-renderer #title,
  #title.ytd-shelf-renderer {
    font-family: var(--fuente-titulos) !important;
    font-weight: 700 !important;
    letter-spacing: 0.5px;
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  }

  /* Logo "YouTube.Mp4" en gótica */
  ytd-topbar-logo-renderer,
  #logo-icon,
  #country-code {
    filter: drop-shadow(0 0 4px rgba(0, 0, 0, 0.7));
  }
  #country-code {
    font-family: var(--fuente-titulos) !important;
    color: #fff !important;
  }

  /* Texto secundario */
  #metadata-line,
  #metadata-line span,
  .ytd-video-meta-block,
  #owner-sub-count {
    color: var(--texto-suave) !important;
  }

  /* ---------- BARRA DE SCROLL ---------- */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #2a0000; }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #ff4a4a, #7a0000);
    border-radius: 10px;
    border: 2px solid #2a0000;
  }

  /* ---------- SELECCIÓN DE TEXTO ---------- */
  ::selection { background: #ff3b3b; color: #fff; }
}
